3	import { isJSONSerializable } from "./utils/internal/object.ts";
4	import { sanitizeStatusCode, sanitizeStatusMessage } from "./utils/sanitize.ts";
5	import { kEventDispose, type DisposeState } from "./utils/internal/dispose.ts";
6	
7	import type { H3Config } from "./types/h3.ts";
8	import { kEventRes, kEventResHeaders, kEventResErrHeaders, type H3Event } from "./event.ts";
9	
10	export const kNotFound: symbol = /* @__PURE__ */ Symbol.for("h3.notFound");
11	export const kHandled: symbol = /* @__PURE__ */ Symbol.for("h3.handled");
12	
13	export function toResponse(
14	  val: unknown,
15	  event: H3Event,
16	  config: H3Config = {},
17	): Response | Promise<Response> {
18	  if (typeof (val as PromiseLike<unknown>)?.then === "function") {
19	    return (val as Promise<unknown>).then(
20	      (resolvedVal) => toResponse(resolvedVal, event, config),
21	      (r) => toResponse(toError(r), event, config),
22	    ) as Promise<Response>;
23	  }
24	
25	  let response: Response | Promise<Response>;
26	  try {
27	    response = prepareResponse(val, event, config);
28	  } catch (error) {
29	    return toResponse(toError(error), event, config);
30	  }
31	  if (typeof (response as PromiseLike<Response>)?.then === "function") {
32	    return toResponse(response, event, config);
33	  }
34	
35	  const { onResponse } = config;
36	  if (onResponse) {
37	    // onResponse is a terminal side-effect hook (returns void). A throw/rejection here must not
38	    // escape the lifecycle (onError already ran); absorb and log it (consistent with dispose
39	    // callbacks), then still return the already-built response. The hook is invoked inside `.then`
40	    // so a synchronous throw is caught too (not just a rejected promise).
41	    return Promise.resolve()
42	      .then(() => onResponse(response as Response, event))
43	      .catch((error) => {
44	        if (!config.silent) console.error(error);
45	      })
46	      .then(
47	        () =>
48	          ((event as any)[kEventDispose] as DisposeState | undefined)?.observe(
49	            response as Response,
50	            val,
51	          ) ?? (response as Response),
52	      );
53	  }
54	  return (
55	    ((event as any)[kEventDispose] as DisposeState | undefined)?.observe(
56	      response as Response,
57	      val,
58	    ) ?? (response as Response)
59	  );
60	}
61	
62	/**
63	 * Normalize a thrown or rejected value before rendering it as a response.
64	 *
65	 * Errors and the internal sentinels are passed through, and numbers are coerced to a status code
66	 * (`throw 404`). Anything else — an object, a string, `undefined` — is wrapped into an unhandled
67	 * 500, so it is logged instead of being rendered as a successful response body.
68	 *
69	 * Nothing is taken from the thrown value: `status`, `message`, `data`, `statusText` and `headers`
70	 * are all dropped, and the value is kept as `cause`, which is never serialized. A non-Error object
71	 * is never trusted to shape the response, not even via a `status` shorthand.
72	 */
73	export function toError(value: unknown): unknown {
74	  if (value === kNotFound || value === kHandled || value instanceof Error) {
75	    return value;
76	  }
77	  if (typeof value === "number") {
78	    return new HTTPError({ status: value });
79	  }
80	  const error = new HTTPError({ status: 500, unhandled: true });
81	  (error as { cause: unknown }).cause = value;
82	  return error;
83	}
84	
85	/**
86	 * Brand for {@link HTTPResponse}, checked instead of `constructor.name`.
87	 *
88	 * A duck-typed name check is forgeable from untrusted input: `JSON.parse` creates an *own*
89	 * `constructor` property, so a request body like `{"constructor":{"name":"HTTPResponse"}}` echoed
90	 * back by a handler would be accepted as a response descriptor and get to pick the response body,
91	 * headers and status. A registry symbol cannot appear in JSON while still matching across
92	 * duplicate module instances (multiple h3 copies, realms).
93	 */
94	const kHTTPResponse: unique symbol = /* @__PURE__ */ Symbol.for("h3.HTTPResponse");
95	
96	export class HTTPResponse {
97	  #headers?: Headers;
98	  #init?: Pick<ResponseInit, "status" | "statusText" | "headers"> | undefined;
99	  body?: BodyInit | null;
100	  constructor(
101	    body: BodyInit | null,
102	    init?: Pick<ResponseInit, "status" | "statusText" | "headers">,
103	  ) {
104	    this.body = body;
105	    this.#init = init;
106	  }
107	  /**
108	   * Status of the response, or `undefined` when unset.
109	   *
110	   * Unset means "inherit": the status staged on `event.res.status` is used, falling back to `200`.
111	   * Defaulting to `200` here instead would make an untouched `HTTPResponse` indistinguishable from
112	   * one explicitly built with `{ status: 200 }`, and always win over `event.res`.
113	   */
114	  get status(): number | undefined {
115	    return this.#init?.status;
116	  }
117	  /** Status text of the response, or `undefined` when unset. See {@link HTTPResponse.status}. */
118	  get statusText(): string | undefined {
119	    return this.#init?.statusText;
120	  }
121	  get headers(): Headers {
122	    return (this.#headers ||= new Headers(this.#init?.headers));
123	  }
124	}
125	
126	// Assigned on the prototype (not as a class field) to keep it out of the public type surface.
127	(HTTPResponse.prototype as any)[kHTTPResponse] = true;
128	
129	function prepareResponse(
130	  val: unknown,
131	  event: H3Event,
132	  config: H3Config,
133	  nested?: boolean,
134	): Response | Promise<Response> {
135	  if (val === kHandled) {
136	    return new FastResponse(null);
137	  }
138	
139	  if (val === kNotFound) {
140	    val = new HTTPError({
141	      status: 404,
142	      message: `Cannot find any route matching [${event.req.method}] ${event.url}`,
143	    });
144	  }
145	
146	  if (val && val instanceof Error) {
147	    const isHTTPError = HTTPError.isError(val);
148	    const error = isHTTPError ? (val as HTTPError) : new HTTPError(val);
149	    if (!isHTTPError) {
150	      // @ts-expect-error unhandled is readonly for public interface
151	      error.unhandled = true;
152	      if (val?.stack) {
153	        error.stack = val.stack;
154	      }
155	    }
156	    if (error.unhandled && !config.silent) {
157	      console.error(error);
158	    }
159	    const { onError } = config;
160	    const errHeaders: Headers | undefined = (event as any)[kEventRes]?.[kEventResErrHeaders];
161	    if (onError && !nested) {
162	      return Promise.resolve()
163	        .then(() => onError(error, event))
164	        .catch(toError)
165	        .then((newVal) => prepareResponse(newVal ?? val, event, config, true));
166	    }
167	    // `errorResponse` merges `errHeaders` into the response it builds, so clear the
168	    // prepared response before rendering. With `onError` configured the rendered
169	    // Response is passed back through `prepareResponse`, which would otherwise merge
170	    // `errHeaders` a second time — harmless for single-valued headers (`set`), but
171	    // `set-cookie` is appended and would be duplicated.
172	    (event as any)[kEventRes] = undefined;
173	    val = errorResponse(error, config.debug, errHeaders);
174	  }
175	
176	  // Only set if event.res.headers is accessed
177	  const preparedRes:
178	    | undefined
179	    | {
180	        status?: number;
181	        statusText?: string;
182	        [kEventResHeaders]?: Headers;
183	        [kEventResErrHeaders]?: Headers;
184	      } = (event as any)[kEventRes];
185	  let preparedHeaders = preparedRes?.[kEventResHeaders];
186	  (event as any)[kEventRes] = undefined; // Clear prepared response to avoid duplication
187	
188	  if (!(val instanceof Response)) {
189	    const res = prepareResponseBody(val, event, config);
190	    // Sanitize on the way out: `event.res.status`/`statusText` and `HTTPResponse` are plain
191	    // user-writable fields, and `FastResponse` defers validation to the runtime. An invalid value
192	    // then throws from Node's `writeHead()` — after `toResponse` returned, so outside every h3
193	    // try/catch — and takes the process down; on runtimes that do not validate the reason phrase,
194	    // a CRLF in `statusText` is response splitting.
195	    const rawStatus = res.status || preparedRes?.status;
196	    const status = rawStatus ? sanitizeStatusCode(rawStatus) : undefined;
197	    const rawStatusText = res.statusText || preparedRes?.statusText;
198	    return new FastResponse(nullBody(event.req.method, status) ? null : res.body, {
199	      status,
200	      statusText: rawStatusText === undefined ? undefined : sanitizeStatusMessage(rawStatusText),
201	      headers:
202	        res.headers && preparedHeaders
203	          ? mergeHeaders(res.headers, preparedHeaders)
204	          : res.headers || preparedHeaders,
205	    });
206	  }
207	
208	  // Success and redirect responses receive all prepared headers.
209	  // Error responses (4xx/5xx) only receive headers explicitly staged as `event.res.errHeaders`
210	  // to avoid leaking success-only headers (caching, content negotiation, ...) into errors.
211	  if (val.status >= 400) {
212	    preparedHeaders = preparedRes?.[kEventResErrHeaders];
213	  }
214	
215	  // Merge prepared headers unless there is nothing to merge or a custom error
216	  // render is returned from `onError`. `event.res.headers` is created lazily on first
217	  // access, so it can be present but empty -- nothing to merge then either.
218	  if (preparedHeaders && !nested && !preparedHeaders.keys().next().done) {
219	    // Never merge *into* `val.headers`: the handler owns that `Response` and may reuse it
220	    // (module-level constant, memoized fallback, ...). Merging in place makes
221	    // request-scoped headers stick to it permanently, and because `set-cookie` is
222	    // appended rather than set, one request's session cookie would then be re-emitted to
223	    // every later client receiving that same object. Build a new response instead.
224	    return new FastResponse(nullBody(event.req.method, val.status) ? null : val.body, {
225	      status: val.status,
226	      statusText: val.statusText,
227	      headers: mergeHeaders(val.headers, preparedHeaders),
228	    }) as Response;
229	  }
230	
231	  // Strip the body for HEAD requests (runtimes usually do this, but keep
232	  // self-consistent for web-mode / service-worker consumers). Covers the
233	  // in-place merge path above, which previously returned the body intact.
234	  return event.req.method === "HEAD" && val.body !== null
235	    ? (new FastResponse(null, {
236	        status: val.status,
237	        statusText: val.statusText,
238	        headers: val.headers,
239	      }) as Response)
240	    : val;
241	}
242	
243	function mergeHeaders(base: HeadersInit, overrides: Headers, target = new Headers(base)): Headers {
244	  for (const [name, value] of overrides) {
245	    if (name === "set-cookie") {
246	      target.append(name, value);
247	    } else {
248	      target.set(name, value);
249	    }
250	  }
251	  return target;
252	}
253	
254	const frozen =
255	  (name: string) =>
256	  (...args: any[]) => {
257	    throw new Error(`Headers are frozen (${name} ${args.join(", ")})`);
258	  };
259	
260	class FrozenHeaders extends Headers {
261	  override set = frozen("set");
262	  override append = frozen("append");
263	  override delete = frozen("delete");
264	}
265	
266	const emptyHeaders = /* @__PURE__ */ new FrozenHeaders({
267	  "content-length": "0",
268	});
269	
270	const jsonHeaders = /* @__PURE__ */ new FrozenHeaders({
271	  "content-type": "application/json;charset=UTF-8",
272	});
273	
274	function prepareResponseBody(
275	  val: unknown,
276	  event: H3Event,
277	  config: H3Config,
278	): Partial<HTTPResponse> {
279	  // Empty Content
280	  if (val === null || val === undefined) {
281	    return { body: "", headers: emptyHeaders };
282	  }
283	
284	  const valType = typeof val;
285	
286	  // Text
287	  if (valType === "string") {
288	    // Default header is text/plain we don't set it for performance reasons
289	    // new Response("").headers.get('content-type') === "text/plain;charset=UTF-8"
290	    return { body: val as string };
291	  }
292	
293	  // Buffer (should be before JSON)
294	  if (val instanceof Uint8Array) {
295	    // Set on the returned headers, not `event.res` (already cleared by the caller):
296	    // writing to `event.res.headers` here would recreate it post-clear and be discarded.
297	    return {
298	      body: val as BufferSource,
299	      headers: new Headers({ "content-length": val.byteLength.toString() }),
300	    };
301	  }
302	
303	  // Partial Response
304	  if (val instanceof HTTPResponse || (val as any)?.[kHTTPResponse] === true) {
305	    return val;
306	  }
307	
308	  // JSON
309	  if (isJSONSerializable(val, valType)) {
310	    return {
311	      body: JSON.stringify(val, undefined, config.debug ? 2 : undefined),
312	      headers: jsonHeaders,
313	    };
314	  }
315	
316	  // BigInt
317	  if (valType === "bigint") {
318	    return { body: val.toString(), headers: jsonHeaders };
319	  }
320	
321	  // Blob
322	  if (val instanceof Blob) {
323	    const headers = new Headers({
324	      "content-type": val.type,
325	      "content-length": val.size.toString(),
326	    });
327	
328	    // File
329	    let filename = (val as File).name;
330	    if (filename) {
331	      filename = encodeURIComponent(filename);
332	      // Omit the disposition type ("inline" or "attachment") and let the client (browser) decide.
333	      headers.set("content-disposition", `filename="${filename}"; filename*=UTF-8''${filename}`);
334	    }
335	
336	    return { body: val.stream(), headers };
337	  }
338	
339	  // Symbol or Function
340	  if (valType === "symbol") {
341	    return { body: val.toString() };
342	  }
343	  if (valType === "function") {
344	    return { body: `${(val as () => unknown).name}()` };
345	  }
346	
347	  return { body: val as BodyInit };
348	}
349	
350	function nullBody(method: string, status: number | undefined): boolean | 0 | undefined {
351	  // prettier-ignore
352	  return (method === "HEAD" ||
353	    status === 100 || status === 101 || status === 102 ||
354	    status === 204 || status === 205 || status === 304
355	  );
356	}
357	
358	function errorResponse(error: HTTPError, debug?: boolean, errHeaders?: Headers): Response {
359	  let headers: Headers = error.headers
360	    ? mergeHeaders(jsonHeaders, error.headers)
361	    : new Headers(jsonHeaders);
362	  if (errHeaders) {
363	    headers = mergeHeaders(headers, errHeaders);
364	  }
365	  return new FastResponse(
366	    JSON.stringify(
367	      {
368	        ...error.toJSON(),
369	        stack: debug && error.stack ? error.stack.split("\n").map((l) => l.trim()) : undefined,
370	      },
371	      undefined,
372	      debug ? 2 : undefined,
373	    ),
374	    {
375	      status: error.status,
376	      statusText: error.statusText,
377	      headers,
378	    },
379	  );
380	}
